    "type": "Múltipla escolha",
    "isAnulada": false,
    "statement": "Os prolactinomas, tumores hipofisários produtores de prolactina (PRL), são os adenomas hipofisários mais frequentes. Em geral, surgem esporadicamente, mas podem se associar a síndromes genéticas, como neoplasia endócrina múltipla tipo 1 e adenoma hipofisário familiar isolado. Considerando as manifestações clínicas associadas aos prolactinomas, é CORRETO afirmar:",
    "options": [
      {
        "letter": "A",
        "text": "A hiperprolactinemia leva ao hipogonadismo hipogonadotrófico, principalmente por inibir a pulsatilidade do hormônio liberador das gonadotrofinas (GnRH)."
      },
      {
        "letter": "B",
        "text": "Clinicamente, as mulheres podem apresentar fase lútea longa, anovulação, infertilidade, oligomenorreia e amenorreia."
      },
      {
        "letter": "C",
        "text": "A hiperprolactinemia crônica leva ao aumento da densidade mineral óssea na coluna lombar em ambos os sexos em razão do hipogonadismo."
      },
      {
        "letter": "D",
        "text": "A compressão da haste hipofisária, do tecido hipofisário normal ou em decorrência da apoplexia hipofisária, leva ao comprometimento dos seios cavernosos."
      }
    ],
    "correctAnswer": "A",
    "commentary": "Gabarito Oficial: Alternativa A."
