    "statement": "**Relacione a Coluna 1 à Coluna 2, associando as síndromes às suas respectivas manifestações:**\n\n### Coluna 1\n\n1. Síndrome de Morris\n2. Síndrome de Savage\n3. Síndrome de Turner\n4. Síndrome de Rokitansky\n5. Síndrome de Kallmann\n\n### Coluna 2\n\n( ) Amenorreia hipergonadotrófica, alteração no receptor de gonadotrofinas, ausência de mamas e presença de pelos pubianos\n\n( ) Amenorreia hipogonadotrófica, anosmia, ausência de mamas e presença de pelos pubianos\n\n( ) Amenorreia hipergonadotrófica, disgenesia gonadal, ausência de mamas e presença de pelos pubianos\n\n( ) Amenorreia hipergonadotrófica, ausência de pelos pubianos e presença de mamas\n\n( ) Amenorreia normogonadotrófica, defeito mülleriano, presença de mamas e de pelos pubianos\n\n**A ordem correta de preenchimento dos parênteses, de cima para baixo, é:**",
