    "statement": "A puberdade é o período em que surgem os caracteres sexuais secundários e o indivíduo adquire a capacidade de reproduzir. As alterações surgem direta ou indiretamente da maturação do hipotálamo, da estimulação dos órgãos sexuais e da secreção de esteroides sexuais. Sobre o desenvolvimento desse período, é CORRETO afirmar:",
