        "text": "Os distúrbios do sistema genital e do útero, envolvendo agenesias ou disgenesias müllerianas, podendo formar uma síndrome de malformações, por vezes incluindo sistema esquelético ou renal, são chamadas de síndrome de Mayer-Rokitansky-Kuster-Hauser."
