    "isAnulada": false,
    "statement": "Usuária do sexo feminino, 19 anos de idade, procura atendimento porque nos últimos 3 anos já fez vários tratamentos para infecção de bexiga, sem sucesso. O último episódio teve início há 12 dias com ardor à micção, polaciúria e noctúria. Aos 6 anos de idade tratou sarcoma uterino com quimio e radioterapia. Nunca menstruou. Sexarca aos 15 anos e de 3 anos para cá percebe secura vaginal e dispareunia profunda. Ao exame físico estatura de 157cm e peso de 51kg, mamas hipoplásicas, pilificação genital escassa, grandes e pequenos lábios hipotróficos. Ao toque simples vagina com amplitude menor que 2 centímetros e colo posterior, puntiforme e com menos de 1 centímetro de diâmetro; corpo a anexos impalpáveis. Ao exame especular diminuição da rugosidade vaginal. Ultrassom pélvico demonstrou útero infantil e ovários atróficos. Teste de progesterona e estrogênio negativos. Dosagem de FSH 168,34 mUI/ml (normal de 3,5 mUI/ml à 134,8 mUI/ml) e de estradiol 2,43 pg/mL (normal de 12,5 pg/mL à 498 pg/mL). Parcial de urina com leucocitúria moderada e sem outras alterações. Urocultura negativa. Em relação à amenorreia que esta paciente apresenta assinale as afirmativas verdadeiras.I – É uma amenorreia primária do compartimento II e III.II – É uma amenorreia primária do compartimento I.III – É uma amenorreia primária do compartimento III e I.IV – É uma amenorreia primária do compartimento II.V – Existe uma falência ovariana precoce.A seguinte alternativa que contempla o enunciado desta questão:",
