    "statement": "A Síndrome dos Ovários Policísticos (SOP) é desordem endócrina mais comum nas mulheres em idade reprodutiva, afetando 4-12% das mulheres. A SOP reveste-se de importância não só pela sua frequência, mas também pelas repercussões à saúde como: obesidade, infertilidade, resistência insulínica, dislipidemia, diabetes gestacional, diabetes mellitus tipo 2, depressão e redução da qualidade de vida. Sobre a fisiopatologia da SOP, marque a opção ERRADA:",
