        "text": "O exame do nível de hormônio folículo estimulante (FSH) é realizado no terceiro dia do ciclo menstrual, reflete a capacidade funcional do hipotálamo e da hipófise que, na proximidade da menopausa, apresenta FSH acima de 2 mUI/ml."
