        "text": "O tratamento cirúrgico é indicado para pacientes com síndromes virilizantes de origem adrenal ou ovariana. MARCONDES JAM, HAYASHIDA SAY. Hirsutismo. EM: LOPES AC e colaboradores. Diagnóstico e tratamento – Sociedade Brasileira e Clínica Médica. Volume 2. Capítulo 35. Manole. 2006."
